pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(100, "Test", "TST"); }
    function testRegression_property() public {
        address owner = address(this);

        c.freezeAccount(owner, false);

        c.burn(1);

        assertTrue(c.frozenAccount(owner) == false);
    }
}
